INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 6 > Integration > Hardware
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist es möglich, Hardware in ein IT-System zu integrieren, ohne deren Treiber zu installieren?', 2, '[{"text": "Nein", "correct": true, "because": "Treiber sind notwendig für die Kommunikation mit dem System"}, {"text": "Ja", "correct": false, "because": "Ohne Treiber fehlt die Funktionalität"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Integration von Hardware in ein bestehendes System ohne Neustart erfolgen?', 2, '[{"text": "Ja", "correct": true, "because": "Hot-Plug-fähige Hardware erlaubt dies"}, {"text": "Nein", "correct": false, "because": "Neustart ist oft, aber nicht immer nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen alle Hardwarekomponenten eines Systems denselben Hersteller haben, um integriert zu werden?', 2, '[{"text": "Nein", "correct": true, "because": "Kompatibilität ist entscheidend, nicht der Hersteller"}, {"text": "Ja", "correct": false, "because": "Heterogene Systeme sind üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Hardwarekomponenten ohne vorherige Planung erfolgreich in ein IT-System integriert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Technisch möglich, aber riskant und ineffizient"}, {"text": "Nein", "correct": false, "because": "Planung ist empfohlen, aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Integration von Hardware immer unabhängig von der Softwarekonfiguration?', 2, '[{"text": "Nein", "correct": true, "because": "Software muss oft angepasst werden"}, {"text": "Ja", "correct": false, "because": "Interaktion zwischen Hardware und Software ist nötig"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme ist vor der Integration neuer Hardware in ein System zwingend erforderlich?', 3, '[{"text": "Überprüfung der Kompatibilität", "correct": true, "because": "Verhindert Systemfehler"}, {"text": "Erstellung eines Benutzerhandbuchs", "correct": false, "because": "Spätere Phase"}, {"text": "Änderung der Netzwerkprotokolle", "correct": false, "because": "Nur bei Bedarf"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schnittstelle wird häufig zur Integration von Peripheriegeräten verwendet?', 2, '[{"text": "USB", "correct": true, "because": "Universell und weit verbreitet"}, {"text": "HDMI", "correct": false, "because": "Primär für Video"}, {"text": "SMTP", "correct": false, "because": "Netzwerkprotokoll, keine Hardware"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Hardware-Integration in ein IT-System?', 2, '[{"text": "Nahtlose Zusammenarbeit mit bestehenden Komponenten", "correct": true, "because": "Stellt Funktionalität sicher"}, {"text": "Reduktion der Stromkosten", "correct": false, "because": "Nebenaspekt"}, {"text": "Verkürzung der Installationszeit", "correct": false, "because": "Nicht primäres Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler kann bei der Integration von Hardware auftreten, wenn Treiber veraltet sind?', 3, '[{"text": "Unvollständige Erkennung der Hardware", "correct": true, "because": "Treiber müssen aktuell sein"}, {"text": "Schnellere Systemleistung", "correct": false, "because": "Unrealistisch"}, {"text": "Automatische Softwareaktualisierung", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug hilft bei der Diagnose von Hardware-Integrationsproblemen?', 2, '[{"text": "Systemprotokolle", "correct": true, "because": "Zeigen Fehler und Status an"}, {"text": "Texteditor", "correct": false, "because": "Nicht für Diagnose geeignet"}, {"text": "Grafiksoftware", "correct": false, "because": "Irrelevant für Hardware"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren müssen bei der Integration von Hardware berücksichtigt werden?', 4, '[{"text": "Kompatibilität mit bestehender Hardware", "correct": true, "because": "Vermeidet Konflikte"}, {"text": "Treiberunterstützung", "correct": true, "because": "Notwendig für Funktion"}, {"text": "Leistungsanforderungen", "correct": true, "because": "Beeinflusst Systemstabilität"}, {"text": "Farbe der Komponenten", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Hardware-Integration auftreten?', 3, '[{"text": "Inkompatible Schnittstellen", "correct": true, "because": "Verhindert Anschluss"}, {"text": "Fehlende Stromversorgung", "correct": true, "because": "Hardware bleibt inaktiv"}, {"text": "Treiberkonflikte", "correct": true, "because": "Führt zu Fehlfunktionen"}, {"text": "Zu schnelle Datenübertragung", "correct": false, "because": "Kein Integrationsproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind bei der Integration neuer Hardware erforderlich?', 4, '[{"text": "Physische Installation", "correct": true, "because": "Hardware muss angeschlossen werden"}, {"text": "Treiberinstallation", "correct": true, "because": "Ermöglicht Kommunikation"}, {"text": "Systemtests", "correct": true, "because": "Überprüft Funktion"}, {"text": "Erstellung eines Logos", "correct": false, "because": "Nicht technisch relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Hardware könnten in ein IT-System integriert werden?', 3, '[{"text": "Festplatten", "correct": true, "because": "Speichererweiterung"}, {"text": "Grafikkarten", "correct": true, "because": "Leistungssteigerung"}, {"text": "Netzwerkadapter", "correct": true, "because": "Netzwerkfähigkeit"}, {"text": "Bürostühle", "correct": false, "because": "Keine IT-Komponente"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ressourcen sind für eine erfolgreiche Hardware-Integration nötig?', 3, '[{"text": "Technische Dokumentation", "correct": true, "because": "Leitet Prozess"}, {"text": "Kompatible Treiber", "correct": true, "because": "Ermöglicht Funktion"}, {"text": "Ausreichende Stromversorgung", "correct": true, "because": "Betreibt Hardware"}, {"text": "Marketingbudget", "correct": false, "because": "Irrelevant für Integration"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Hardware-Integration erfordert oft eine Anpassung der Software. b) Alle Hardwarekomponenten sind automatisch kompatibel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Software ja, Kompatibilität nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Hot-Plug-Hardware kann ohne Abschalten integriert werden. b) Hardware-Integration ist unabhängig von Betriebssystemen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hot-Plug ja, OS beeinflusst Integration"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein BIOS-Update kann die Hardware-Integration erleichtern. b) Hardwaretests sind nach der Integration überflüssig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "BIOS ja, Tests nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Inkompatible Hardware kann Systemabstürze verursachen. b) Jede Hardware lässt sich in jedes System integrieren.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Abstürze ja, Integration begrenzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Hardware-Integration kann zusätzliche Stromkapazität erfordern. b) Treiberinstallation ist bei moderner Hardware überflüssig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Strom ja, Treiber oft nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

